import React, { useState, useEffect } from 'react';
import { BrowserRouter, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, useAuth } from './context/AuthContext';

// Components
import Login from './components/auth/Login';
import ProtectedRoute from './components/auth/ProtectedRoute';
import Navbar from './components/layout/Navbar';
import Sidebar from './components/layout/Sidebar';

// Pages
import DashboardPage from './pages/DashboardPage';
import ConfiguracionPage from './pages/ConfiguracionPage';
import AlumnosPage from './pages/AlumnosPage';
import ChatPage from './pages/ChatPage';

// Layout para páginas protegidas
const AppLayout = ({ children, asignaciones }) => {
  return (
    <div className="min-h-screen bg-gray-50">
      <Navbar />
      <Sidebar asignaciones={asignaciones} />
      <main className="ml-64 pt-16 p-6">
        {children}
      </main>
    </div>
  );
};

// Componente principal con estado de asignaciones
const AppContent = () => {
  const { isAuthenticated } = useAuth();
  const [asignaciones, setAsignaciones] = useState([]);

  // Cargar asignaciones del localStorage
  useEffect(() => {
    if (isAuthenticated) {
      const stored = localStorage.getItem('asignaciones');
      if (stored) {
        setAsignaciones(JSON.parse(stored));
      }
    }
  }, [isAuthenticated]);

  // Guardar asignaciones
  const handleAddAsignacion = (nueva) => {
    const updated = [...asignaciones, nueva];
    localStorage.setItem('asignaciones', JSON.stringify(updated));
    setAsignaciones(updated);
  };

  const handleDeleteAsignacion = (id) => {
    const updated = asignaciones.filter(a => a.id !== id);
    localStorage.setItem('asignaciones', JSON.stringify(updated));
    setAsignaciones(updated);
  };

  return (
    <Routes>
      {/* Ruta pública */}
      <Route 
        path="/login" 
        element={isAuthenticated ? <Navigate to="/dashboard" replace /> : <Login />} 
      />

      {/* Rutas protegidas */}
      <Route
        path="/dashboard"
        element={
          <ProtectedRoute>
            <AppLayout asignaciones={asignaciones}>
              <DashboardPage asignaciones={asignaciones} />
            </AppLayout>
          </ProtectedRoute>
        }
      />

      <Route
        path="/configuracion"
        element={
          <ProtectedRoute>
            <AppLayout asignaciones={asignaciones}>
              <ConfiguracionPage
                asignaciones={asignaciones}
                onAddAsignacion={handleAddAsignacion}
                onDeleteAsignacion={handleDeleteAsignacion}
              />
            </AppLayout>
          </ProtectedRoute>
        }
      />

      <Route
        path="/alumnos/:grado/:division/:materiaId"
        element={
          <ProtectedRoute>
            <AppLayout asignaciones={asignaciones}>
              <AlumnosPage asignaciones={asignaciones} />
            </AppLayout>
          </ProtectedRoute>
        }
      />

      <Route
        path="/chat/:grado/:division/:materiaId"
        element={
          <ProtectedRoute>
            <AppLayout asignaciones={asignaciones}>
              <ChatPage asignaciones={asignaciones} />
            </AppLayout>
          </ProtectedRoute>
        }
      />

      {/* Redirect por defecto */}
      <Route path="/" element={<Navigate to="/dashboard" replace />} />
      <Route path="*" element={<Navigate to="/dashboard" replace />} />
    </Routes>
  );
};

function App() {
  return (
    <BrowserRouter>
      <AuthProvider>
        <AppContent />
      </AuthProvider>
    </BrowserRouter>
  );
}

export default App;
